    "controllerInstruction": "シートベルト着用中の衝突で、車内での頭部打撲後にめまいが出現。神経局在なし、歩行不能、嘔気を提示する。点滴開始後、合図で腹痛を訴えさせ、下腹部の帯状皮下出血（シートベルト痕）、BP 86/58・HR 122、FAST陽性、造影CTで腸管損傷＋腸間膜損傷による腹腔内出血を提示。軽症ゾーンから救外への移送、外科コンサルト、緊急開腹と術後ICU入室の調整を判断させる。学生には手術決定が伝えられるまで、かなり強い腹痛を訴え続けさせる。",
    "controllerChecklist": "□ 下腹部のシートベルト痕に気づく\n□ 軽症ゾーンでバイタルと腹部所見を反復評価\n□ 腹痛出現時にFASTを実施し陰性でも再検を検討\n□ 赤へアップトリアージし救外へ移送\n□ 外科コンサルトと造影CTを手配\n□ 緊急開腹の手術室と術後ICUを同時に調整",
    "actingPoints": "開眼でめまい増強。点滴後にめまいは改善するが、コントローラーの合図で腹痛を訴える。以後は手術が決まったと伝えられるまで、かなり強い腹痛を訴え続け、腹部を押さえてぐったりする。",
    "focus": "軽症ゾーンでの再評価、シートベルト痕からの遅発性腸管・腸間膜損傷の想起、FASTの活用、緊急手術の手配、術後ICU調整",
    "learningPoints": "腹壁の帯状皮下出血（シートベルト徴候）を見たら腸管・腸間膜損傷とChance骨折を疑う。\n腸管・腸間膜損傷は初期のFAST・診察で所見が乏しく、遅発性にショック化する。\n軽症ゾーンに振り分けた患者でも反復評価とアップトリアージが不可欠。\n災害時は緊急手術枠と術後ICUベッドを同時に確保する。",
    "branchConditions": "対応できた場合: 腹痛出現直後に再評価し、輸液・輸血を行いながら緊急開腹へ進め、循環を保ったまま術後ICUへ入室できる。\n遅れた場合: 「めまいの患者」という先入観で経過観察され、BP 70台・HR 130へ進行して筋性防御が明らかになり、腹膜炎・敗血症へ進展する。",
    "moulage": "下腹部に斜めの帯状皮下出血・擦過傷（シートベルト痕）",
    "originalId": "22",
