    "overview": "張碓の多重事故で搬入された身元不明の小児赤症例。救急車で救外へ直行。張碓付近の多重事故に巻き込まれた身元不明の中学生。重症頭部外傷（急性硬膜下血腫）に加え、頭部の大きな裂創からの活動性出血により出血性ショックを呈す。気道確保・頭皮止血・輸血で循環は安定し、初期CTでは血腫は少量で緊急手術の適応なくICU入室となるが、ICU入室後に瞳孔不同が出現し血腫増大で緊急開頭術となる。",
    "rescueVitals": "BP 90/60（来院時、。頭部裂創・皮下血腫、呼びかけにうめくのみ、末梢冷感を伴う外傷性ショック。",
    "primaryTriageFindings": "歩行不能、呼びかけにうめき声のみ、頭皮裂創からの出血を伴うショックバイタル",
    "initialVitals": "BP 90/60（来院時、。頭部裂創・皮下血腫、呼びかけにうめくのみ、末梢冷感を伴う外傷性ショック",
    "exam": "来院時は瞳孔左右差・明らかな四肢麻痺なし。",
    "tests": "頭部CTで少量の急性硬膜下血腫。正中偏位・脳浮腫はなし。FASTは陰性。ICU入室後に瞳孔不同が出現し、再検CTで血腫増大を確認。",
    "treatment": "気管挿管（RSI）、頭皮止血・輸血。初期CTでは緊急手術の適応なく、挿管管理のままICU入室し経過観察。ICU入室後の瞳孔不同・血腫増大を受けて緊急開頭血腫除去術。術後もICU管理。",
    "additionalEvent": "気道確保（RSI）と頭皮止血・輸血の同時進行。止血・輸血後にバイタルは安定し、初期CTでは緊急手術の適応なくICU入室。ICU入室後の良いタイミングで瞳孔不同が出現し、CT再検で血腫増大、緊急手術となる二段階の展開。ICUと手術室の連絡調整が必要。",
    "controllerInstruction": "初期CTは少量の急性硬膜下血腫で正中偏位・脳浮腫なし、FAST陰性と提示し、脳神経外科は緊急手術不要と判断させる。頭皮止血・輸血後はバイタル安定を伝え、挿管管理のままICU入室へ。ICU入室後の良いタイミングで瞳孔不同の出現を伝え、CT再検で血腫増大を提示して緊急手術へ移行させる。ICUと手術室の連絡・緊急手術の受け入れ調整を評価する。",
    "controllerChecklist": "□ GCS 8で頸椎保護下のRSIによる気管挿管を実施\n□ 頭皮裂創を圧迫・縫合/ステープルで止血\n□ 輸血を開始し、他部位の出血源をFASTなどで検索\n□ 初期CTの所見を脳神経外科と共有し方針を確認\n□ 挿管管理のままICU入室を調整\n□ ICUで瞳孔・GCSを反復評価し、瞳孔不同出現時にCTを再検\n□ ICUから手術室・脳神経外科へ緊急開頭を要請し受け入れを調整\n□ 身元不明患者としての登録・緊急輸血・家族探索を並行",
    "actingPoints": "中学生役は学生が演じる（学生演技）。身元不明。来院時は呼びかけにうめくのみで反応が乏しい。ICU入室後、コントローラーの指示のタイミングで片側瞳孔が散大する（アニソコリア）。",
    "focus": "小児の頭皮出血によるショック、気道確保、ICUでの反復的な神経学的観察と急変時の緊急手術調整（ICU-手術室連携）、身元不明対応",
    "learningPoints": "小児は頭皮出血だけでも出血性ショックに至るため、同時に他部位の出血源も検索する。\n低酸素・低血圧を避けることが二次性脳損傷予防の鍵で、GCS≤8は気道確保の適応。\n初期CTが軽微でも急性硬膜下血腫は増大しうるため、ICUで瞳孔・GCSを反復評価しCT再検の閾値を低く保つ。\nICU・手術室・脳神経外科の連携と、身元不明患者への対応（推定体重での薬剤投与・緊急輸血）。",
    "branchConditions": "対応できた場合: 挿管と頭皮止血・輸血でBP 120/70と循環が安定し、ICUでの反復評価により瞳孔不同を直ちに捕らえてCT再検→緊急開頭血腫除去術へ短時間で移行できる。\n遅れた場合: 挿管が遅れれば舌根沈下・低換気で頭蓋内圧が上昇しCPAに至る。止血・輸血が遅れれば出血性ショックが増悪し二次性脳損傷を助長する。ICUでの瞳孔変化を見逃す・CT再検や手術室連絡が遅れると、テント切痕ヘルニアが進行し不可逆的脳損傷となる。",
    "moulage": "頭部の大きな裂創からの活動性出血、皮下血腫、顔面血液付着",
