    "careGuide": "【コントローラー】初回バイタル「BP 74/42、HR 140、SpO2 94%RA、RR 30」と診察所見「顔面蒼白、冷汗著明、左骨盤部圧痛・変形、骨盤動揺性あり。」を提示。検査：骨盤X線/CT: 不安定型骨盤骨折。TAE後: Hb 7.2へ低下、乳酸 5.0mmol/L。\n治療判断を確認：サムスリング固定、輸液・輸血、TAE（AG）で止血。TAE後も血圧が不安定で輸血継続を要し、骨盤内パッキング・創外固定を検討のうえICU入室。\nチェック：□ 歩行可能に見えても赤へトリアージアップし救外へ誘導\n□ 骨盤ベルト（サムスリング）を早期に装着\n□ 骨盤動揺性の反復診察を避ける\n□ 輸液・輸血（大量輸血プロトコル）を開始\n□ AG室へTAEを依頼し搬送を調整\n□ TAE後に再評価し、輸血継続とICU入室を依頼",
    "careWindow": "3-12分",
    "escalationGuide": "【コントローラー】追加イベント：乗用車1で来院。一見歩けそうに見えるが骨盤骨折によるショックで、トリアージアップして救外ゾーンへ直接誘導する判断を促す。TAE終了後にERで血圧再低下と乳酸上昇を付与し、輸血継続とICU入室依頼を判断させる（演技不要、コントローラーが数値で提示）。\n分岐：対応できた場合: 骨盤固定と輸血でBP 90台へ改善し、TAE後もICUで循環管理・輸血継続につなげられる。\n遅れた場合: 後腹膜出血が進行しBP 60台・HR 150へ。動揺性の反復診察や晶質液のみの補正で凝固障害が加わり循環虚脱に至る。\n【傷病者役】刺激で開眼するがすぐ閉眼。意味のある会話は困難。左骨盤部を触られると痛みで反応。",
    "escalationWindow": "12-20分（該当時）",
    "mediaGuide": "【モニター】プレイヤーがモニター装着を依頼した時点で、コントローラーは「モニター画面のQRコード」を提示し、BP 74/42、HR 140、SpO2 94%RA、RR 30を確認させる。\n【画像】プレイヤーが骨盤X線またはCT撮影を決定した時点で、「画像のQRコード」を提示する。不安定型骨盤骨折を確認後に、TAE後のHb 7.2、乳酸 5.0を数値で提示する。",
    "notes": "ムラージュ：不要\n学習ポイント：不安定型骨盤骨折では、骨盤の外固定と早期止血が重要。動揺性の反復診察は再出血を招くため避ける。TAE後も循環が不安定なら再出血・他部位出血を検索し、ICUで輸血を継続する。"
