    "arrivalWindow": "0-3分",
    "careGuide": "【コントローラー】初回バイタル：BP 118/70、HR 88、SpO2 98%RA、RR 16\n診察所見：眼振あり、四肢麻痺なし。下腹部に斜めの帯状皮下出血・擦過（シートベルト痕）。腹痛出現後は臍周囲〜下腹部に強い圧痛と筋性防御、腸雑音低下。\n治療判断：点滴・鎮痛のうえ経過観察としたが、腹痛出現後にFAST陽性・造影CTで腸管損傷＋腸間膜損傷による腹腔内出血を確認し、シートベルト損傷として外科で緊急開腹（止血・損傷腸管の処理）。腹部術後のためICU管理。\n進行指示：シートベルト着用中の衝突で、車内での頭部打撲後にめまいが出現。神経局在なし、歩行不能、嘔気を提示する。点滴開始後、合図で腹痛を訴えさせ、下腹部の帯状皮下出血（シートベルト痕）、BP 86/58・HR 122、FAST陽性、造影CTで腸管損傷＋腸間膜損傷による腹腔内出血を提示。軽症ゾーンから救外への移送、外科コンサルト、緊急開腹と術後ICU入室の調整を判断させる。学生には手術決定が伝えられるまで、かなり強い腹痛を訴え続けさせる。\n確認項目：□ 下腹部のシートベルト痕に気づく\n□ 軽症ゾーンでバイタルと腹部所見を反復評価\n□ 腹痛出現時にFASTを実施し陰性でも再検を検討\n□ 赤へアップトリアージし救外へ移送\n□ 外科コンサルトと造影CTを手配\n□ 緊急開腹の手術室と術後ICUを同時に調整",
    "careWindow": "3-12分",
    "escalationGuide": "【コントローラー】追加イベント：乗用車1の同乗者として来院（シートベルト着用）。軽症ゾーンで点滴中（来院約30分後）に腹痛を訴える。下腹部のシートベルト痕に気づけるかを含め、遅発性に腹部所見が出現するシートベルト損傷（腸管・腸間膜損傷）として、軽症ゾーンから救外への移送、緊急手術と術後ICUの手配につなげる判断を促す。\n分岐・悪化条件：対応できた場合: 腹痛出現直後に再評価し、輸液・輸血を行いながら緊急開腹へ進め、循環を保ったまま術後ICUへ入室できる。\n遅れた場合: 「めまいの患者」という先入観で経過観察され、BP 70台・HR 130へ進行して筋性防御が明らかになり、腹膜炎・敗血症へ進展する。\n【傷病者役】開眼でめまい増強。点滴後にめまいは改善するが、コントローラーの合図で腹痛を訴える。以後は手術が決まったと伝えられるまで、かなり強い腹痛を訴え続け、腹部を押さえてぐったりする。",
    "escalationWindow": "12-20分（該当時）",
    "mediaGuide": "【モニター】プレイヤーがモニター装着を依頼した時点で、「モニター画面のQRコード」を提示し、BP 118/70、HR 88、SpO2 98%RA、RR 16を確認させる。\n【検査・画像】プレイヤーが検査または画像撮影を決定した時点で、「検査・画像のQRコード」を提示する。確認後に、頭部MRI異常なし。腹痛出現後: FAST陽性（モリソン窩・骨盤内に液体貯留）。造影CTで腸間膜からの造影剤漏出と腸管壁の血流不良、腹腔内液体貯留、腹壁のシートベルト痕に一致する皮下血腫。Hb 9.2、乳酸 4.2mmol/L。を提示する。",
    "notes": "ムラージュ：下腹部に斜めの帯状皮下出血・擦過傷（シートベルト痕）\n学習ポイント：腹壁の帯状皮下出血（シートベルト徴候）を見たら腸管・腸間膜損傷とChance骨折を疑う。\n腸管・腸間膜損傷は初期のFAST・診察で所見が乏しく、遅発性にショック化する。\n軽症ゾーンに振り分けた患者でも反復評価とアップトリアージが不可欠。\n災害時は緊急手術枠と術後ICUベッドを同時に確保する。"
