    "careWindow": "3-12分",
    "escalationGuide": "【コントローラー】追加イベント：乗用車2で来院。同乗者から「車内に動けない人がいる」と情報提供させる。\n分岐・悪化条件：対応できた場合: 輸液・輸血でBP 100/60台・HR 100前後へ改善し、TAE後は循環安定してEU入院。\n遅れた場合: BP 60台、HR 140、意識レベル低下と冷汗増強、Hb低下を提示し、出血性ショックの進行を示す。\n【傷病者役】一次までは軽い左背部痛。二次直前に座位で意識消失。臥位で意識回復後、左背部痛を強く訴える。",
