    "mediaGuide": "【モニター】プレイヤーがモニター装着を依頼した時点で、「モニター画面のQRコード」を提示し、BP 76/30、HR 132、SpO2 96%RA。臥位では意識清明を確認させる。\n【検査・画像】プレイヤーが検査または画像撮影を決定した時点で、「検査・画像のQRコード」を提示する。確認後に、FAST陰性。造影CT: 左腎損傷、造影剤血管外漏出あり。を提示する。",
