    "careGuide": "【コントローラー】初回バイタル：実測値で安定\n診察所見：バレー陽性、右上下肢軽度脱力。\n治療判断：脳卒中対応（画像評価・適応判断）。EU入院で神経所見を監視。\n進行指示：乗用車4。スーパーで倒れた後の体動困難として登場させ、右上下肢脱力と構音障害を提示。二次トリアージで救外移動を判断させる。\n確認項目：□右上下肢の脱力と呂律不良を提示する\n□二次トリアージで神経所見（バレー徴候・構音）を取り直すか\n□発症時刻／最終未発症時刻を確認するか\n□軽症ゾーンから救外へ移動し脳卒中コードを起動できるか\n□画像評価と再灌流療法の適応判断ができるか",
    "careWindow": "3-12分",
    "escalationGuide": "【コントローラー】追加イベント：乗用車4の同乗者として来院。軽症ゾーン混雑時に紛れ込ませ、再評価とゾーン間連絡を確認。\n分岐・悪化条件：二次トリアージで神経所見を評価し救外へ振り分けた場合: 適応に応じてrt-PA・血栓回収療法へ進める。\n「歩けるから緑」と判断し軽症ゾーンで待機させた場合: 治療可能時間を逸失し梗塞が不可逆的に拡大する。\n発症時刻が不明のまま経過した場合: 再灌流療法の適応判断が遅れる。\n【傷病者役】右足が出しにくく、少し呂律が回らない。",
