    "mediaGuide": "【モニター】プレイヤーがモニター装着を依頼した時点で、「モニター画面のQRコード」を提示し、実測値で安定を確認させる。\n【検査・画像】プレイヤーが検査または画像撮影を決定した時点で、「検査・画像のQRコード」を提示する。確認後に、MRIで脳梗塞。を提示する。",
    "notes": "ムラージュ：記載なし\n学習ポイント：脳梗塞は歩行可能でも緊急度が高く、片麻痺・構音障害はトリアージアップの根拠となる。\nrt-PA（発症4.5時間以内）や血栓回収療法の適応は発症時刻に依存するため、最終未発症時刻の確認が最重要。\n二次トリアージで神経所見を取り直す再評価が鍵となる。\n災害時でも内因性疾患は発生し、限られた画像・人的資源の中で適応を判断する。"
